//! The conformance gate (pat-mgixk.403).
//!
//! Boots every project under `engine-rs/fixtures/conformance/` in-process
//! through the runner's own project boot, diffs its trace envelope against the
//! headless-Godot 4.6.1 golden captured by
//! `tools/oracle/conformance_capture.py`, and prints a per-project PASS/FAIL
//! table.
//!
//! # Why this exists
//!
//! The 2026-10-30 port audit found 93 UNWIRED and 19 STUB features behind beads
//! that had closed green. Every `*_parity_test.rs` in this repo compares Patina
//! against *itself*: a golden generated by Patina, re-read by Patina. Such a
//! suite is green the moment our writer and our reader agree, whatever Godot
//! actually does. The goldens this file reads were produced by real Godot — so
//! a feature nothing is wired to shows up as a FAIL here even when its own
//! bead's test passes.
//!
//! # The ratchet
//!
//! `fixtures/golden/conformance/baseline.json` carries `min_passing` (a floor
//! the measured pass count may never drop below) and `expected_failing` (the
//! projects that MUST still fail, which is what proves the gate can see a gap
//! instead of passing everything vacuously). Both are checked here.

use std::collections::BTreeSet;
use std::path::{Path, PathBuf};
use std::sync::Mutex;

use patina_runner::conformance::{self, Envelope, ProjectReport};

/// `project_boot::boot_project` installs the process-global `res://` path roots
/// and ClassDB registrations, so two tests booting projects at once would read
/// each other's roots. A per-process test runner isolates each test and does
/// not need this; a thread-per-test runner does.
static BOOT_LOCK: Mutex<()> = Mutex::new(());

fn engine_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn projects_dir() -> PathBuf {
    engine_dir().join("fixtures").join("conformance")
}

fn golden_dir() -> PathBuf {
    engine_dir()
        .join("fixtures")
        .join("golden")
        .join("conformance")
}

fn oracle_dir() -> PathBuf {
    engine_dir()
        .parent()
        .expect("engine-rs has a parent directory")
        .join("tools")
        .join("oracle")
}

/// The checked-in ratchet.
struct Baseline {
    min_passing: usize,
    expected_failing: BTreeSet<String>,
}

fn load_baseline() -> Baseline {
    let path = golden_dir().join("baseline.json");
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("cannot read ratchet baseline {}: {e}", path.display()));
    let value: serde_json::Value = serde_json::from_str(&text)
        .unwrap_or_else(|e| panic!("{} is not valid JSON: {e}", path.display()));
    let min_passing = value
        .get("min_passing")
        .and_then(serde_json::Value::as_u64)
        .unwrap_or_else(|| panic!("{} has no integer `min_passing`", path.display()))
        as usize;
    let expected_failing = value
        .get("expected_failing")
        .and_then(serde_json::Value::as_array)
        .map(|entries| {
            entries
                .iter()
                .filter_map(|v| v.as_str().map(str::to_string))
                .collect()
        })
        .unwrap_or_default();
    Baseline {
        min_passing,
        expected_failing,
    }
}

/// Every golden on disk, by project name, sorted.
fn golden_names() -> Vec<String> {
    let dir = golden_dir();
    let entries =
        std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("cannot list {}: {e}", dir.display()));
    let mut names: Vec<String> = entries
        .filter_map(Result::ok)
        .filter_map(|entry| {
            let path = entry.path();
            if path.extension().and_then(|e| e.to_str()) != Some("json") {
                return None;
            }
            let stem = path.file_stem()?.to_str()?.to_string();
            // The ratchet lives in the same directory and is not a golden.
            if stem == "baseline" {
                return None;
            }
            Some(stem)
        })
        .collect();
    names.sort();
    names
}

/// Boots one project and diffs it against its golden.
fn gate_one(name: &str) -> ProjectReport {
    let golden_path = golden_dir().join(format!("{name}.json"));
    let text = std::fs::read_to_string(&golden_path)
        .unwrap_or_else(|e| panic!("cannot read golden {}: {e}", golden_path.display()));
    let value: serde_json::Value = serde_json::from_str(&text)
        .unwrap_or_else(|e| panic!("{} is not valid JSON: {e}", golden_path.display()));
    let golden = Envelope::from_json(&value).unwrap_or_else(|e| {
        panic!(
            "{} is not a conformance envelope: {e}",
            golden_path.display()
        )
    });

    let project_dir = projects_dir().join(name);
    assert!(
        project_dir.join("project.godot").is_file(),
        "golden {} has no project at {}: a golden without its project cannot be \
         re-measured, so the gate would silently stop covering it",
        golden_path.display(),
        project_dir.display()
    );

    // The one call that matters: the project goes through the runner's own
    // project boot, its real MainLoop frames and its real script bridge. No
    // helper in this file touches the scene tree.
    //
    // Wrapped in `catch_unwind` on purpose. A project that panics the runner is
    // the loudest possible conformance failure, and it belongs in the table as
    // one FAIL row — letting the panic escape would instead kill the whole run
    // and hide the verdict on every other project behind it.
    let captured = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        conformance::capture_project(
            &project_dir,
            golden.frames.max(1),
            conformance::DEFAULT_DELTA,
        )
    }));

    let failure = match captured {
        Ok(Ok(actual)) => return conformance::diff(&golden, &actual),
        // A project the runner cannot even boot is a FAIL, not a skip — a clean
        // "could not boot" is exactly the kind of gap this gate exists to
        // surface.
        Ok(Err(e)) => format!("runner could not boot the project: {e}"),
        Err(payload) => {
            let message = payload
                .downcast_ref::<&str>()
                .map(|s| (*s).to_string())
                .or_else(|| payload.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "<non-string panic payload>".to_string());
            format!("runner PANICKED while running the project: {message}")
        }
    };
    ProjectReport {
        project: name.to_string(),
        passed: false,
        failures: vec![failure],
        notes: Vec::new(),
    }
}

fn run_gate() -> Vec<ProjectReport> {
    let names = golden_names();
    assert!(
        !names.is_empty(),
        "no conformance goldens under {} — the gate measures nothing. \
         Capture them with `python3 tools/oracle/conformance_capture.py`.",
        golden_dir().display()
    );
    names.iter().map(|name| gate_one(name)).collect()
}

fn print_table(reports: &[ProjectReport]) {
    println!("\n=== conformance gate (Patina vs headless Godot 4.6.1) ===");
    for report in reports {
        println!("  {}", report.table_row());
        for failure in &report.failures {
            println!("      FAIL  {failure}");
        }
        for note in &report.notes {
            println!("      note  {note}");
        }
    }
    let passed = reports.iter().filter(|r| r.passed).count();
    println!("  --- {passed}/{} projects pass ---\n", reports.len());
}

/// Acceptance (pat-mgixk.403): every conformance project boots through
/// `patina_runner`, is diffed against its headless-Godot golden, and the
/// measured pass count holds the checked-in ratchet.
#[test]
fn conformance_gate_ratchet() {
    let _guard = BOOT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let baseline = load_baseline();
    let reports = run_gate();
    print_table(&reports);

    let passing: BTreeSet<&str> = reports
        .iter()
        .filter(|r| r.passed)
        .map(|r| r.project.as_str())
        .collect();

    assert!(
        passing.len() >= baseline.min_passing,
        "conformance REGRESSION: {} of {} projects pass, the ratchet floor is {}. \
         Passing now: {:?}. The floor only ever moves up — see \
         fixtures/golden/conformance/baseline.json.",
        passing.len(),
        reports.len(),
        baseline.min_passing,
        passing
    );

    for name in &baseline.expected_failing {
        let report = reports
            .iter()
            .find(|r| &r.project == name)
            .unwrap_or_else(|| {
                panic!(
                    "baseline.json lists `{name}` in expected_failing, but there is no \
                     golden for it. Remove the entry or capture the project."
                )
            });
        assert!(
            !report.passed,
            "`{name}` is listed in baseline.json's expected_failing but now PASSES. \
             That is progress, not a bug: drop it from expected_failing and raise \
             min_passing to {}.",
            passing.len()
        );
    }

    println!(
        "measured pass count = {} (ratchet floor {}). To ratchet, set \
         min_passing to {} in fixtures/golden/conformance/baseline.json.",
        passing.len(),
        baseline.min_passing,
        passing.len()
    );
}

/// The gate has to be able to FAIL, or it certifies nothing.
///
/// If this test ever fails it means every conformance project now matches real
/// Godot — genuinely good news, and the signal to add harder projects rather
/// than to relax anything here.
#[test]
fn conformance_gate_can_see_a_difference_from_godot() {
    let _guard = BOOT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let reports = run_gate();
    let passed = reports.iter().filter(|r| r.passed).count();
    assert!(
        passed < reports.len(),
        "all {} conformance projects match Godot exactly. Either the diff has \
         stopped comparing anything, or the corpus is too easy — add projects \
         that reach further into the runtime.",
        reports.len()
    );
}

/// Every golden has a project, and every project has a golden. A project with
/// no golden is invisible to the gate, which is how coverage quietly rots.
#[test]
fn every_conformance_project_has_a_golden() {
    let dir = projects_dir();
    let entries =
        std::fs::read_dir(&dir).unwrap_or_else(|e| panic!("cannot list {}: {e}", dir.display()));
    let projects: BTreeSet<String> = entries
        .filter_map(Result::ok)
        .filter(|entry| entry.path().join("project.godot").is_file())
        .filter_map(|entry| entry.file_name().into_string().ok())
        .collect();
    let goldens: BTreeSet<String> = golden_names().into_iter().collect();

    assert!(
        !projects.is_empty(),
        "no conformance projects under {}",
        dir.display()
    );
    let ungolden: Vec<&String> = projects.difference(&goldens).collect();
    assert!(
        ungolden.is_empty(),
        "these conformance projects have no Godot golden, so the gate never \
         measures them: {ungolden:?}. Capture with \
         `python3 tools/oracle/conformance_capture.py`."
    );
    let orphaned: Vec<&String> = goldens.difference(&projects).collect();
    assert!(
        orphaned.is_empty(),
        "these goldens have no project to re-measure: {orphaned:?}"
    );
}

/// The Godot-side capture tool and the probe it injects must both be present:
/// without them a golden can never be re-recorded, and a gate whose ground
/// truth cannot be regenerated is a snapshot, not an oracle.
#[test]
fn the_godot_capture_tool_is_checked_in() {
    let tools = oracle_dir();
    for name in ["conformance_capture.py", "conformance_probe.gd"] {
        let path = tools.join(name);
        assert!(
            path.is_file(),
            "{} is missing — the conformance goldens could not be re-captured",
            path.display()
        );
    }
    // The marker is the contract between the two sides: Godot gives a script no
    // hook on `print()`, so the capture reads marker-prefixed lines off stdout
    // while Patina filters the same prefix out of its script buffers. If the
    // two spellings drift, every print comparison silently compares nothing.
    let capture = std::fs::read_to_string(tools.join("conformance_capture.py"))
        .expect("capture tool readable");
    let declaration = format!("PRINT_MARKER = \"{}\"", conformance::PRINT_MARKER);
    assert!(
        capture.contains(&declaration),
        "tools/oracle/conformance_capture.py does not declare `{declaration}`; \
         the Godot and Patina sides would filter different prefixes"
    );
}

/// Guards the other half of that contract: the probe's tracked-property list
/// and the Rust one have to name the same properties, or a property Godot
/// records is one Patina never looks up (and vice versa).
#[test]
fn tracked_property_lists_agree_across_the_two_engines() {
    let probe = oracle_dir().join("conformance_probe.gd");
    let source = std::fs::read_to_string(&probe)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", probe.display()));
    let block = source
        .split("const TRACKED_PROPERTIES := [")
        .nth(1)
        .and_then(|rest| rest.split(']').next())
        .unwrap_or_else(|| panic!("{} has no TRACKED_PROPERTIES list", probe.display()));

    let probe_names: BTreeSet<String> = block
        .split(',')
        .filter_map(|piece| {
            let trimmed = piece.trim().trim_matches('"').trim();
            if trimmed.is_empty() {
                None
            } else {
                Some(trimmed.to_string())
            }
        })
        .collect();
    let rust_names: BTreeSet<String> = conformance::TRACKED_PROPERTIES
        .iter()
        .map(|name| (*name).to_string())
        .collect();

    assert_eq!(
        probe_names, rust_names,
        "tools/oracle/conformance_probe.gd and conformance::TRACKED_PROPERTIES \
         track different properties"
    );
}

/// `fixtures/conformance/*` must stay plain Godot projects: the capture injects
/// its probe into a COPY, so a probe checked into a fixture would mean the
/// golden was recorded from a project that is not the one Patina boots.
#[test]
fn conformance_fixtures_carry_no_probe_wiring() {
    for entry in std::fs::read_dir(projects_dir()).expect("projects dir") {
        let dir: PathBuf = entry.expect("dir entry").path();
        let settings = dir.join("project.godot");
        if !settings.is_file() {
            continue;
        }
        let text = std::fs::read_to_string(&settings).expect("project.godot readable");
        assert!(
            !text.contains("conformance_probe"),
            "{} names the oracle probe; the fixture must stay a plain project",
            settings.display()
        );
        assert!(
            !dir.join("override.cfg").exists(),
            "{} contains an override.cfg; the capture generates that in its \
             temporary copy and must not leave one behind",
            dir.display()
        );
        assert!(
            Path::new(&dir).join("main.tscn").is_file(),
            "{} has no main.tscn",
            dir.display()
        );
    }
}
